// displayWireAPI builds a display-naming handler over a fresh store seeded
// with one serial library (the module-default-shape element template, group
// style left at the "" = clean default), one ready series carrying BOTH a
// parser title and a stored series override, one composed episode item, and
// one fact-free item (the "" floor). Returns the handler, the store, the
// library id, the series row, and the two item ids.
func displayWireAPI(t *testing.T) (http.Handler, *store.Store, int64, store.Series, string, string) {
	t.Helper()
	st := openAPIStore(t)
	ctx := context.Background()
	libID, err := st.CreateLibrary(ctx, "serial", "/media/wire", "Wire")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}
	if _, err := st.UpdateLibrary(ctx, libID, nil, nil, nil, nil,
		strPtr("{title} · S{season}E{episode}")); err != nil {
		t.Fatalf("UpdateLibrary naming options: %v", err)
	}
	sr := seedSeries(t, st, libID, "Атланта (2016)",
		`{"sources":{"serial-parser":{"title":"Атланта"}}}`, "ready")
	if _, err := st.SetTitleOverride(ctx, sr.ID, "Моё сериальное имя"); err != nil {
		t.Fatalf("SetTitleOverride series: %v", err)
	}
	episodeID, filmID := "itm_episode1", "itm_film1"
	seedItemDoc(t, st, libID, episodeID, "Атланта (2016)/S02E06.mkv",
		`{"parsed":{"series_relative_path":"Атланта (2016)"},"sources":{"serial-parser":{"season":2,"episode":6}},"_view":{"title":{"value":"Атланта S02E06.mkv"}}}`)
	seedItemDoc(t, st, libID, filmID, "Обложка альбома.flac", `{"ffprobe":{}}`)
	h := New(Deps{AdminToken: adminToken, Store: st, Scan: func(context.Context, int64) (scan.Result, error) {
		return scan.Result{}, nil
	}})
	return h, st, libID, sr, episodeID, filmID
}

// seedItemDoc puts one item with an explicit id, relative path, and document.
func seedItemDoc(t *testing.T, st *store.Store, libraryID int64, id, relPath, docJSON string) {
	t.Helper()
	err := st.PutItem(context.Background(), store.Item{
		ID: id, ModuleID: "serial", LibraryID: libraryID, FileID: id,
		RelativePath: relPath, MediaType: "serial",
		Document: json.RawMessage(docJSON), SchemaVersion: 1,
	})
	if err != nil {
		t.Fatalf("PutItem %s: %v", id, err)
	}
}

