// rawObject decodes one response body into a generic object map, descending
// the single-noun wrappers (itemResponse{"item":...}, seriesResponse
// {"series":...}) so callers see the DTO's own fields.
func rawObject(t *testing.T, resp *http.Response, wrapper string) map[string]json.RawMessage {
	t.Helper()
	defer resp.Body.Close()
	var top map[string]json.RawMessage
	if err := json.NewDecoder(resp.Body).Decode(&top); err != nil {
		t.Fatalf("decode body: %v", err)
	}
	raw, ok := top[wrapper]
	if !ok {
		t.Fatalf("body missing %q wrapper: %v", wrapper, top)
	}
	var m map[string]json.RawMessage
	if err := json.Unmarshal(raw, &m); err != nil {
		t.Fatalf("decode %s: %v", wrapper, err)
	}
	return m
}

