// rawItems decodes a listing body's items into generic object maps.
func rawItems(t *testing.T, resp *http.Response) []map[string]json.RawMessage {
	t.Helper()
	defer resp.Body.Close()
	var lr struct {
		Items []map[string]json.RawMessage `json:"items"`
	}
	if err := json.NewDecoder(resp.Body).Decode(&lr); err != nil {
		t.Fatalf("decode listing: %v", err)
	}
	return lr.Items
}

// TestDisplayNameWire covers display-naming 3.1: every served item row (list
// AND detail) and series row (list AND detail) carries `display_name` on the
// wire — empty string, never an absent field — and the served chains hold:
// the composed episode name flows through the SERIES override first (the
// composed {title} tier is seriesDisplayTitle), while the item's own
// override still beats the composed name; the fact-free item floors to "".
func TestDisplayNameWire(t *testing.T) {
	h, st, libID, sr, episodeID, filmID := displayWireAPI(t)
	ctx := context.Background()

	t.Run("item_list_display_name_every_row", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(libID), "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		rows := rawItems(t, resp)
		if len(rows) != 2 {
			t.Fatalf("items = %d rows, want 2", len(rows))
		}
		byID := map[string]string{}
		for _, row := range rows {
			byID[rawID(t, row)] = displayField(t, row)
		}
		// The composed name's {title} tier is the SERIES override — the
		// series rename reaches composed episode names (D-9 point read).
		if got := byID[episodeID]; got != "Моё сериальное имя · S02E06" {
			t.Fatalf("episode display_name = %q, want %q", got, "Моё сериальное имя · S02E06")
		}
		// The fact-free item floors honestly: "" present, never fabricated.
		if got := byID[filmID]; got != "" {
			t.Fatalf("film display_name = %q, want the empty floor", got)
		}
	})

	t.Run("item_detail_display_name", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+episodeID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := displayField(t, rawObject(t, resp, "item")); got != "Моё сериальное имя · S02E06" {
			t.Fatalf("detail display_name = %q, want the composed name", got)
		}
	})

	t.Run("item_own_override_beats_composed", func(t *testing.T) {
		if _, err := st.SetTitleOverride(ctx, episodeID, "Моё название"); err != nil {
			t.Fatalf("SetTitleOverride item: %v", err)
		}
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+episodeID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := displayField(t, rawObject(t, resp, "item")); got != "Моё название" {
			t.Fatalf("detail display_name = %q, want the item's own override", got)
		}
	})

	t.Run("series_list_display_name_every_row", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(libID), "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		rows := rawItems(t, resp)
		if len(rows) != 1 {
			t.Fatalf("series = %d rows, want 1", len(rows))
		}
		// The series chain's first tier is its own override.
		if got := displayField(t, rows[0]); got != "Моё сериальное имя" {
			t.Fatalf("series display_name = %q, want the override tier", got)
		}
	})

	t.Run("series_detail_display_name", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+sr.ID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := displayField(t, rawObject(t, resp, "series")); got != "Моё сериальное имя" {
			t.Fatalf("series detail display_name = %q, want the override tier", got)
		}
	})
}

// TestDisplayNameMissingLibraryFloor pins the shared namerFor floor at the
// routes: a VANISHED library row must never turn a previously-200 route into
// a 500. With the library row deleted the namer is empty — no element
// template, no series map — so every route still answers 200 and
// display_name renders from the floor tiers (the item's _view title, the
// series' own stored override), "" when nothing resolves; the field stays
// PRESENT on every served row, never an absent key.
func TestDisplayNameMissingLibraryFloor(t *testing.T) {
	h, st, libID, sr, episodeID, filmID := displayWireAPI(t)
	if _, err := st.DB().ExecContext(context.Background(),
		`DELETE FROM libraries WHERE id = ?`, libID); err != nil {
		t.Fatalf("delete library row: %v", err)
	}

	t.Run("item_detail_200_view_floor", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+episodeID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d (a missing library row must never 500)", resp.StatusCode, http.StatusOK)
		}
		// Empty namer: no element template, the composed leg is gone, and the
		// _view.title floor serves instead of a fabricated name.
		if got := displayField(t, rawObject(t, resp, "item")); got != "Атланта S02E06.mkv" {
			t.Fatalf("detail display_name = %q, want the _view floor tier", got)
		}
	})

	t.Run("item_detail_empty_floor_when_nothing_resolves", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items/"+filmID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if got := displayField(t, rawObject(t, resp, "item")); got != "" {
			t.Fatalf("film display_name = %q, want the empty floor (present, never an absent key)", got)
		}
	})

	t.Run("series_detail_200_override_tier", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+sr.ID, "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d (a missing library row must never 500)", resp.StatusCode, http.StatusOK)
		}
		if got := displayField(t, rawObject(t, resp, "series")); got != "Моё сериальное имя" {
			t.Fatalf("series detail display_name = %q, want the override tier (still first under the empty namer)", got)
		}
	})

	t.Run("series_episodes_200_view_floor", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/series/"+sr.ID+"/episodes", "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d (a missing library row must never 500)", resp.StatusCode, http.StatusOK)
		}
		rows := rawItems(t, resp)
		if len(rows) != 1 {
			t.Fatalf("episodes = %d rows, want 1", len(rows))
		}
		if got := rawID(t, rows[0]); got != episodeID {
			t.Fatalf("episode id = %q, want %q", got, episodeID)
		}
		if got := displayField(t, rows[0]); got != "Атланта S02E06.mkv" {
			t.Fatalf("episode display_name = %q, want the _view floor tier", got)
		}
	})

	t.Run("listings_stay_200_on_missing_library", func(t *testing.T) {
		resp := doRequest(t, h, http.MethodGet, "/api/v1/items?library="+itoa64(libID), "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("items status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if rows := rawItems(t, resp); len(rows) != 2 {
			t.Fatalf("items = %d rows, want 2 (the orphaned rows still serve)", len(rows))
		}
		resp = doRequest(t, h, http.MethodGet, "/api/v1/series?library="+itoa64(libID), "", adminToken)
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("series status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if rows := rawItems(t, resp); len(rows) != 1 {
			t.Fatalf("series = %d rows, want 1", len(rows))
		}
	})
}
